"use strict";(()=>{var s=["11","12","13","14","15","16","17","18","19","21","22","24","27","28","31","32","33","34","35","37","38","41","42","43","44","45","46","47","48","49","51","53","54","55","61","62","64","63","65","66","67","68","69","71","73","74","75","77","79","81","87","82","83","84","85","88","86","89","91","93","94","92","97","95","96","98","99"];var g=class{mask(t){return t=t.replace(/\D/g,"").slice(0,11),t.length<=2?t=t.replace(/^(\d{1,2})/,"($1"):t.length<=7?t=t.replace(/^(\d{2})(\d+)/,"($1) $2"):t=t.replace(/^(\d{2})(\d{5})(\d{0,4})/,"($1) $2-$3"),t}getRawDigits(t){return t.replace(/\D/g,"")}checkLength(t){return this.getRawDigits(t).length===11?!0:"O n\xFAmero deve conter exatamente 11 d\xEDgitos."}checkDDD(t){let e=this.getRawDigits(t).slice(0,2);return s.includes(e)?!0:"O DDD \xE9 inv\xE1lido."}checkFirstDigit(t){return this.getRawDigits(t)[2]==="9"?!0:"O n\xFAmero deve come\xE7ar com 9 ap\xF3s o DDD."}validate(t){let i=[this.checkLength.bind(this),this.checkDDD.bind(this),this.checkFirstDigit.bind(this)].map(r=>r(t)).filter(r=>r!==!0);return i.length===0?!0:i}};})();
